table.script:
// Force a refresh of the report when it's opened
$(document).ready(function() {
    console.log("Document ready, refreshing report data");

    // Log all checkboxes for debugging
    var allCheckboxes = $('input[type="checkbox"]');
    console.log("Found " + allCheckboxes.length + " checkboxes");

    // Log all user_selection fields for debugging
    var userSelectionDebug = $('.vendor-col div small:contains("user_selection")');
    console.log("Found " + userSelectionDebug.length + " user_selection debug elements");
    userSelectionDebug.each(function() {
        console.log("Debug value:", $(this).text());
    });

    // Highlight confirmed purchase orders
    highlightConfirmedOrders();

    // Add a small delay to ensure the DOM is fully loaded
    setTimeout(function() {
        // Force a refresh of the selection badges
        allCheckboxes.each(function() {
            var checkbox = $(this);
            var isChecked = checkbox.prop('checked');
            var name = checkbox.attr('name');
            var value = checkbox.val();

            console.log("Checkbox:", name, value, "Checked:", isChecked);

            // Check if the corresponding PO has user_selection=True
            var vendorId = value;
            if (name === 'vendor_user_selection') {
                // For product selections, extract vendor_id from value (format: vendor_id_tender_line_id)
                vendorId = value.split('_')[0];
            }

            // Find the debug element for this vendor
            var debugElement = $('th.vendor-col[data-vendor-id="' + vendorId + '"] div small:contains("user_selection")');
            if (debugElement.length > 0) {
                var debugText = debugElement.text();
                console.log("Debug for vendor " + vendorId + ":", debugText);

                // If the debug text indicates user_selection is True, check the checkbox
                if (debugText.indexOf("user_selection: True") >= 0 || debugText.indexOf("user_selection: true") >= 0) {
                    console.log("Setting checkbox checked for vendor " + vendorId);
                    checkbox.prop('checked', true);
                    isChecked = true;
                }
            }

            if (isChecked) {
                console.log("Processing checked checkbox:", name, value);
                var cell = checkbox.closest('td');
                if (cell) {
                    cell.addClass('user-selection');
                }

                // Make sure the badge exists
                var badgeContainer = checkbox.parent();
                var existingBadge = badgeContainer.find('.selection-badge.user-badge');
                if (!existingBadge.length) {
                    var badge = $('K');
                    badgeContainer.append(badge);
                }

                // If this is a total selection, update the vendor column header
                if (name === 'vendor_user_total_selection') {
                    var vendorColumn = $('th.vendor-col[data-vendor-id="' + vendorId + '"]');
                    if (vendorColumn.length > 0) {
                        vendorColumn.addClass('user-selection');
                        var headerBadge = vendorColumn.find('.selection-badge.user-badge');
                        if (!headerBadge.length) {
                            var badge = $('Kullanıcı');
                            vendorColumn.append(badge);
                        }
                    }
                }
            }
        });
    }, 500);
});

// Function to handle checkbox selection (only one per row)
function handleCheckboxSelection(checkbox) {
    try {
        // Find the parent row of the checkbox
        var row = checkbox.closest('tr');

        // Get all checkboxes within this row
        var checkboxesInRow = row.querySelectorAll('input[type="checkbox"]');

        // Uncheck all other checkboxes in the same row
        checkboxesInRow.forEach(function(cb) {
            if (cb !== checkbox && checkbox.checked) {
                cb.checked = false;
            }
        });

        // Update UI immediately
        var cell = checkbox.closest('td');
        if (cell) {
            if (checkbox.checked) {
                cell.classList.add('user-selection');

                // Add badge if it doesn't exist
                var badgeContainer = checkbox.parentElement;
                var existingBadge = badgeContainer.querySelector('.selection-badge.user-badge');
                if (!existingBadge) {
                    var badge = document.createElement('span');
                    badge.className = 'selection-badge user-badge ml-2';
                    badge.style.color = 'white'; // Ensure text is visible
                    badge.textContent = 'K';
                    badgeContainer.appendChild(badge);
                }
            } else {
                cell.classList.remove('user-selection');

                // Remove badge if it exists
                var badgeContainer = checkbox.parentElement;
                var existingBadge = badgeContainer.querySelector('.selection-badge.user-badge');
                if (existingBadge) {
                    existingBadge.remove();
                }
            }
        }
    } catch (e) {
        console.error("Error in handleCheckboxSelection:", e);
    }

    // Save the selection to the database
    var tenderId = document.querySelector('table[data-tender-id]').dataset.tenderId;
    var isProductSelection = checkbox.name === 'vendor_user_selection';
    var isTotalSelection = checkbox.name === 'vendor_user_total_selection';
    var isChecked = checkbox.checked;
    var value = checkbox.value;

    console.log("Saving selection:", {
        tenderId: tenderId,
        isProductSelection: isProductSelection,
        isTotalSelection: isTotalSelection,
        isChecked: isChecked,
        value: value
    });

    // Call the server action to save the selection
    $.ajax({
        url: '/web/dataset/call_kw/ak.tender/save_user_selection',
        type: 'POST',
        dataType: 'json',
        contentType: 'application/json',
        data: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                model: 'ak.tender',
                method: 'save_user_selection',
                args: [parseInt(tenderId), value, isProductSelection, isTotalSelection, isChecked],
                kwargs: {}
            },
            id: Math.floor(Math.random() * 1000000000)
        }),
        headers: {
            'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
        },
        success: function(result) {
            console.log("Selection saved successfully", result);

            // Check if the result contains an error
            if (result.error) {
                console.error("Error saving selection:", result.error);
                alert("Seçim kaydedilirken hata oluştu: " + result.error);
                return;
            }

            // Log additional debug info if available
            if (result.result && result.result.debug_info) {
                console.log("Debug info:", result.result.debug_info);
            }

            // Add or remove the badge based on the checkbox state
            var badgeContainer = checkbox.parentElement;
            var existingBadge = badgeContainer.querySelector('.selection-badge.user-badge');

            if (isChecked) {
                // Add badge if it doesn't exist
                if (!existingBadge) {
                    var badge = document.createElement('span');
                    badge.className = 'selection-badge user-badge ml-2';
                    badge.style.color = 'white'; // Ensure text is visible
                    badge.textContent = 'K';
                    badgeContainer.appendChild(badge);
                }

                // Add user-selection class to the parent cell
                var cell = checkbox.closest('td');
                if (cell) {
                    cell.classList.add('user-selection');
                }

                // If this is a total selection, update the vendor column headers
                if (checkbox.name === 'vendor_user_total_selection') {
                    var vendorId = checkbox.value;
                    var vendorColumns = document.querySelectorAll('th.vendor-col');
                    vendorColumns.forEach(function(col) {
                        if (col.dataset.vendorId === vendorId) {
                            col.classList.add('user-selection');
                            // Add badge if it doesn't exist
                            var headerBadge = col.querySelector('.selection-badge.user-badge');
                            if (!headerBadge) {
                                var badge = document.createElement('span');
                                badge.className = 'selection-badge user-badge ml-2';
                                badge.style.color = 'white'; // Ensure text is visible
                                badge.style.textAlign = 'center'; // Center text in badge
                                badge.textContent = 'Kullanıcı';
                                col.appendChild(badge);
                            }
                        }
                    });
                }
            } else {
                // Remove badge if it exists
                if (existingBadge) {
                    existingBadge.remove();
                }

                // Remove user-selection class from the parent cell
                var cell = checkbox.closest('td');
                if (cell) {
                    cell.classList.remove('user-selection');
                }

                // If this is a total selection, update the vendor column headers
                if (checkbox.name === 'vendor_user_total_selection') {
                    var vendorId = checkbox.value;
                    var vendorColumns = document.querySelectorAll('th.vendor-col');
                    vendorColumns.forEach(function(col) {
                        if (col.dataset.vendorId === vendorId) {
                            col.classList.remove('user-selection');
                            // Remove badge if it exists
                            var headerBadge = col.querySelector('.selection-badge.user-badge');
                            if (headerBadge) {
                                headerBadge.remove();
                            }
                        }
                    });
                }
            }
        },
        error: function(error) {
            console.error("Error saving selection:", error);

            // Simple error message
            alert("Seçim kaydedilirken hata oluştu!");

            // Revert the checkbox state
            checkbox.checked = !checkbox.checked;
        }
    });
}

// Function to create orders from selection

function createOrderFromSelection(button) {
    // Get the selected checkboxes for product selections
    var selectedProducts = document.querySelectorAll('input[name="vendor_product_selection"]:checked');
    var selections = [];

    selectedProducts.forEach(function(checkbox) {
        selections.push(checkbox.value);
    });

    if (selections.length > 0) {
        // Call the server action to create orders using jQuery AJAX
        $.ajax({
            url: '/web/dataset/call_kw/ak.tender/create_orders_from_selections',
            type: 'POST',
            dataType: 'json',
            contentType: 'application/json',
            data: JSON.stringify({
                jsonrpc: "2.0",
                method: "call",
                params: {
                    model: 'ak.tender',
                    method: 'create_orders_from_selections',
                    args: [parseInt(button.closest('table').dataset.tenderId), selections],
                    kwargs: {}
                },
                id: Math.floor(Math.random() * 1000000000)
            }),
            headers: {
                'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
            },
            success: function(result) {
                alert("Siparişler oluşturuldu!");
                location.reload();
            },
            error: function(error) {
                console.error("Error creating orders:", error);
                alert("Sipariş oluşturulurken hata oluştu!");
            }
        });
    } else {
        alert("Lütfen en az bir ürün seçin!");
    }
}

function createOrderFromTotalSelection(button) {
    console.log("Starting createOrderFromTotalSelection");

    // Get the selected checkboxes for total selections
    // This function converts existing RFQs to Purchase Orders for selected vendors
    var selectedVendors = document.querySelectorAll('input[name="vendor_user_total_selection"]:checked');

    if (selectedVendors.length === 0) {
        // Also try to get vendor checkboxes with a different name
        selectedVendors = document.querySelectorAll('input[name="vendor_checkbox"]:checked');
    }

    if (selectedVendors.length === 0) {
        alert("Lütfen en az bir tedarikçi seçin!");
        return;
    }

    var vendorIds = [];

    // Get the tender ID from the table data attribute
    var table = document.querySelector('table.comparison-table');
    var tenderId = table ? parseInt(table.dataset.tenderId) : null;

    // If tender ID is not found in the table, try to get it from the URL
    if (!tenderId) {
        var urlParams = new URLSearchParams(window.location.search);
        var activeId = urlParams.get('active_id');
        if (activeId) {
            tenderId = parseInt(activeId);
        }
    }

    if (!tenderId) {
        alert("İhale ID'si bulunamadı!");
        return;
    }

    // Always set to "to approve" state when using this button
    var isEvaluation = true;

    console.log("Tender ID:", tenderId);
    console.log("Is in evaluation stage:", isEvaluation);

    // Extract vendor IDs from selected checkboxes
    selectedVendors.forEach(function(checkbox) {
        vendorIds.push(parseInt(checkbox.value));
    });

    console.log("Selected vendor IDs:", vendorIds);

    if (vendorIds.length === 0) {
        alert("Lütfen en az bir tedarikçi seçin!");
        return;
    }

    // First try to get purchase orders directly from the page
    var purchaseOrderIds = [];
    var vendorColumns = document.querySelectorAll('th.vendor-col');

    vendorColumns.forEach(function(column) {
        var vendorId = column.getAttribute('data-vendor-id');
        if (vendorId && vendorIds.includes(parseInt(vendorId))) {
            // Check if this vendor has a purchase order
            var poState = null;
            var stateText = column.textContent.trim().toLowerCase();

            if (stateText.includes('satınalma siparişi')) {
                poState = 'purchase';
            } else if (stateText.includes('onayda')) {
                poState = 'to approve';
            } else if (stateText.includes('rfq gönderildi')) {
                poState = 'sent';
            } else if (stateText.includes('rfq') && !stateText.includes('gönderildi')) {
                poState = 'draft';
            } else if (stateText.includes('kilitli')) {
                poState = 'done';
            } else if (stateText.includes('iptal')) {
                poState = 'cancel';
            }

            if (poState && (poState === 'draft' || poState === 'sent' || poState === 'to approve')) {
                purchaseOrderIds.push(parseInt(vendorId));
            }
        }
    });

    console.log("Purchase order IDs from page:", purchaseOrderIds);

    // If we found purchase orders on the page, use them
    if (purchaseOrderIds.length > 0) {
        console.log("Using purchase orders found on page");
        if (isEvaluation) {
            setToApproveState(purchaseOrderIds);
        } else {
            confirmPurchaseOrders(purchaseOrderIds);
        }
        return;
    }

    // If we didn't find purchase orders on the page, try to get them from the server
    console.log("No purchase orders found on page, trying server");

    // Get the purchase orders directly from the tender
    $.ajax({
        url: '/web/dataset/call_kw/ak.tender/read',
        type: 'POST',
        dataType: 'json',
        contentType: 'application/json',
        data: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                model: 'ak.tender',
                method: 'read',
                args: [tenderId, ['purchase_order_ids']],
                kwargs: {}
            },
            id: Math.floor(Math.random() * 1000000000)
        }),
        headers: {
            'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
        },
        success: function(result) {
            if (result.error) {
                console.error("Error reading tender:", result.error);
                alert("İhale bilgileri okunurken hata oluştu!");
                return;
            }

            console.log("Tender read result:", result.result);

            if (result.result && result.result[0] && result.result[0].purchase_order_ids && result.result[0].purchase_order_ids.length > 0) {
                // Get all purchase orders from the tender
                var allPoIds = result.result[0].purchase_order_ids;
                console.log("All PO IDs from tender:", allPoIds);

                // Now get the details of these purchase orders to filter by vendor
                $.ajax({
                    url: '/web/dataset/call_kw/purchase.order/read',
                    type: 'POST',
                    dataType: 'json',
                    contentType: 'application/json',
                    data: JSON.stringify({
                        jsonrpc: "2.0",
                        method: "call",
                        params: {
                            model: 'purchase.order',
                            method: 'read',
                            args: [allPoIds, ['partner_id', 'state']],
                            kwargs: {}
                        },
                        id: Math.floor(Math.random() * 1000000000)
                    }),
                    headers: {
                        'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
                    },
                    success: function(poResult) {
                        if (poResult.error) {
                            console.error("Error reading purchase orders:", poResult.error);
                            alert("Siparişler okunurken hata oluştu!");
                            return;
                        }

                        console.log("PO details:", poResult.result);

                        // Filter purchase orders by vendor and state
                        var filteredPoIds = [];
                        poResult.result.forEach(function(po) {
                            console.log("Checking PO:", po);
                            console.log("  Partner ID:", po.partner_id);
                            console.log("  State:", po.state);
                            console.log("  Vendor IDs:", vendorIds);
                            console.log("  Includes:", vendorIds.includes(po.partner_id[0]));

                            if (po.partner_id && vendorIds.includes(po.partner_id[0]) &&
                                (po.state === 'draft' || po.state === 'sent' || po.state === 'to approve')) {
                                filteredPoIds.push(po.id);
                            }
                        });

                        console.log("Filtered PO IDs:", filteredPoIds);

                        if (filteredPoIds.length > 0) {
                            // If in evaluation stage, set to "to approve" status, otherwise confirm
                            if (isEvaluation) {
                                setToApproveState(filteredPoIds);
                            } else {
                                confirmPurchaseOrders(filteredPoIds);
                            }
                        } else {
                            // Try a broader search without state filter
                            var anyPoIds = [];
                            poResult.result.forEach(function(po) {
                                if (po.partner_id && vendorIds.includes(po.partner_id[0])) {
                                    anyPoIds.push(po.id);
                                }
                            });

                            console.log("Any PO IDs (without state filter):", anyPoIds);

                            if (anyPoIds.length > 0) {
                                console.log("Found POs but they are not in the right state");
                                alert("Seçilen tedarikçiler için siparişler bulundu, ancak uygun durumda değiller!");
                            } else {
                                console.log("No matching purchase orders found for the selected vendors");
                                alert("Seçilen tedarikçiler için sipariş bulunamadı! Lütfen önce siparişlerin oluşturulduğundan emin olun.");
                            }
                        }
                    },
                    error: function(error) {
                        console.error("Error reading purchase orders:", error);
                        alert("Siparişler okunurken hata oluştu!");
                    }
                });
            } else {
                console.log("No purchase orders found in the tender");
                alert("İhalede hiç sipariş bulunamadı! Lütfen önce siparişlerin oluşturulduğundan emin olun.");
            }
        },
        error: function(error) {
            console.error("Error reading tender:", error);
            alert("İhale bilgileri okunurken hata oluştu!");
        }
    });

}

// Function to confirm purchase orders
function confirmPurchaseOrders(poIds) {
    $.ajax({
        url: '/web/dataset/call_kw/purchase.order/button_confirm',
        type: 'POST',
        dataType: 'json',
        contentType: 'application/json',
        data: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                model: 'purchase.order',
                method: 'button_confirm',
                args: [poIds],
                kwargs: {}
            },
            id: Math.floor(Math.random() * 1000000000)
        }),
        headers: {
            'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
        },
        success: function(result) {
            if (result.error) {
                console.error("Error confirming purchase orders:", result.error);
                alert("Siparişler onaylanırken hata oluştu!");
                return;
            }

            // Highlight the confirmed vendors and their products
            highlightConfirmedOrders(poIds);

            alert("Seçilen tedarikçinin teklifi siparişe dönüştürüldü!");
            // Don't reload the page so we can see the highlighting
        },
        error: function(error) {
            console.error("Error confirming purchase orders:", error);
            alert("Siparişler onaylanırken hata oluştu!");
        }
    });
}

// Function to set purchase orders to "to approve" state directly
function setToApproveState(poIds) {
    $.ajax({
        url: '/web/dataset/call_kw/purchase.order/button_to_approve',
        type: 'POST',
        dataType: 'json',
        contentType: 'application/json',
        data: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                model: 'purchase.order',
                method: 'button_to_approve',
                args: [poIds],
                kwargs: {}
            },
            id: Math.floor(Math.random() * 1000000000)
        }),
        headers: {
            'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
        },
        success: function(result) {
            if (result.error) {
                console.error("Error setting purchase orders to approve state:", result.error);
                alert("Siparişler onay durumuna alınırken hata oluştu!");
                return;
            }

            alert("Seçilen tedarikçinin teklifi onay durumuna alındı!");
            location.reload();
        },
        error: function(error) {
            console.error("Error setting purchase orders to approve state:", error);
            alert("Siparişler onay durumuna alınırken hata oluştu!");
        }
    });
}

// Function to highlight confirmed orders and their products
function highlightConfirmedOrders(poIds) {
    console.log("Highlighting confirmed orders");

    // Find all vendor columns
    var vendorColumns = document.querySelectorAll('th.vendor-col');
    var confirmedVendorIds = [];

    // Find all status cells in the table
    var rows = document.querySelectorAll('tr');

    // Look for cells containing "Purchase"
    rows.forEach(function(row) {
        var cells = row.querySelectorAll('td');
        cells.forEach(function(cell, cellIndex) {
            var text = cell.textContent.trim();
            if (text.indexOf('Satınalma Siparişi') >= 0) {
                console.log("Found Satınalma Siparişi in:", text);

                // Find the vendor for this row
                var vendorName = row.querySelector('td:first-child');
                if (vendorName) {
                    console.log("Vendor:", vendorName.textContent.trim());

                    // Find matching vendor column
                    vendorColumns.forEach(function(column) {
                        if (column.textContent.indexOf(vendorName.textContent.trim()) >= 0) {
                            // Add confirmed class
                            column.classList.add('confirmed-order');

                            // Add badge
                            var badge = document.createElement('span');
                            badge.className = 'confirmed-badge';
                            badge.style.color = 'white'; // Ensure text is visible
                            badge.style.textAlign = 'center'; // Center text in badge
                            badge.textContent = 'Satınalma Siparişi';
                            column.appendChild(badge);

                            console.log("Highlighted vendor column:", column);
                        }
                    });
                }
            }
        });
    });
}

// Function to set purchase orders to "to approve" state directly
function setToApproveState(poIds) {
    $.ajax({
        url: '/web/dataset/call_kw/purchase.order/write',
        type: 'POST',
        dataType: 'json',
        contentType: 'application/json',
        data: JSON.stringify({
            jsonrpc: "2.0",
            method: "call",
            params: {
                model: 'purchase.order',
                method: 'write',
                args: [poIds, {'state': 'to approve'}],
                kwargs: {}
            },
            id: Math.floor(Math.random() * 1000000000)
        }),
        headers: {
            'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]') ? document.querySelector('meta[name="csrf-token"]').getAttribute('content') : ''
        },
        success: function(result) {
            if (result.error) {
                console.error("Error setting purchase orders to approve state:", result.error);
                alert("Siparişler onay durumuna alınırken hata oluştu!");
                return;
            }

            alert("Seçilen tedarikçinin teklifi onay durumuna alındı!");
            location.reload();
        },
        error: function(error) {
            console.error("Error setting purchase orders to approve state:", error);
            alert("Siparişler onay durumuna alınırken hata oluştu!");
        }
    });
}
